_SAVE_OP_BY_FORMAT: dict[str, str] = {
    "pptx": "presentationfile.save",
    "xlsx": "spreadsheetfile.save",
}

_FILE_IMPORT_OPS: dict[tuple[str, str], tuple[str, str]] = {
    ("PresentationFile", "importPptx"): ("presentationfile.load", "pptx"),
    ("SpreadsheetFile", "importXlsx"): ("spreadsheetfile.load", "xlsx"),
}

_FILE_EXPORT_OPS: dict[tuple[str, str], tuple[str, str]] = {
    ("PresentationFile", "exportPptx"): ("presentationfile.save", "pptx"),
    ("SpreadsheetFile", "exportXlsx"): ("spreadsheetfile.save", "xlsx"),
}


@dataclass(frozen=True)
class Blob:
    data: bytes
    mime: str | None = None
    source_path: str | None = None
    artifact_handle: str | None = None
    artifact_format: str | None = None
    artifact_save_op: str | None = None

    @classmethod
    def load(cls, path: str | Path) -> Blob:
        mime, _ = mimetypes.guess_type(str(path))
        with open(path, "rb") as f:
            return cls(f.read(), mime=mime, source_path=str(path))

    def render(self) -> Image.Image:
        assert self.mime is not None and self.mime.startswith("image/"), (
            "Only images can be rendered"
        )

        return Image.open(BytesIO(self.data))

    def to_base64(self) -> str:
        return base64.b64encode(self.data).decode("utf-8")

    def to_data_url(self) -> str:
        return f"data:{self.mime or 'application/octet-stream'};base64,{self.to_base64()}"

    def save(self, path: str | Path) -> None:
        path_obj = Path(path)
        path_obj.parent.mkdir(parents=True, exist_ok=True)
        with open(path_obj, "wb") as f:
            f.write(self.data)
        save_op = self.artifact_save_op or _SAVE_OP_BY_FORMAT.get(self.artifact_format or "")
        if self.artifact_handle and self.artifact_format and save_op:
            client = get_client()
            if client is not None:
                client.record_artifact_operation(
                    self.artifact_handle,
                    {
                        "op": save_op,
                        "path": str(path_obj),
                        "format": self.artifact_format,
                    },
                )

    # ---------------------------
    # Jupyter/IPython display hooks
    # ---------------------------

    def _as_png_bytes(self) -> bytes | None:
        if not (self.mime and self.mime.startswith("image/")):
            return None

        if self.mime == "image/png":
            return self.data

        # Convert other image types to PNG for display.
        img = self.render()
        buf = BytesIO()
        img.save(buf, format="PNG")
        return buf.getvalue()

    def _repr_png_(self) -> bytes | None:
        """
        IPython hook: return raw PNG bytes.
        IPython will handle encoding to the Jupyter wire format.
        """
        return self._as_png_bytes()

    def _repr_mimebundle_(
        self,
        include: set[str] | None = None,
        exclude: set[str] | None = None,
    ) -> dict[str, Any]:
        """
        IPython hook: explicit MIME bundle.
        We provide image/png when possible.
        """
        png = self._as_png_bytes()
        if png is None:
            return {"text/plain": f"Blob(mime={self.mime!r}, bytes={len(self.data)})"}

        # For the Jupyter wire protocol, image/png is base64 text.
        b64_png = base64.b64encode(png).decode("ascii")
        return {
            "image/png": b64_png,
            "text/plain": f"Blob(image/png, bytes={len(png)})",
        }


def _should_preserve_key(key: Any) -> bool:
    return not isinstance(key, str) or key.startswith(("$", "__")) or "-" in key


def _camelize_key(key: Any) -> Any:
    if _should_preserve_key(key):
        return key
    return humps.camelize(key)


def _decamelize_key(key: Any) -> Any:
    if _should_preserve_key(key):
        return key
    return humps.decamelize(key)


def _camelize_data(value: Any) -> Any:
    if isinstance(value, dict):
        return {_camelize_key(k): _camelize_data(v) for k, v in value.items()}
    if isinstance(value, list):
        return [_camelize_data(v) for v in value]
    if isinstance(value, tuple):
        return [_camelize_data(v) for v in value]
    return value


def _decamelize_data(value: Any) -> Any:
    if isinstance(value, dict):
        return {_decamelize_key(k): _decamelize_data(v) for k, v in value.items()}
    if isinstance(value, list):
        return [_decamelize_data(v) for v in value]
    return value


def _wire_attr(name: str, *, preserve_snake_case: bool = False) -> str:
    if "-" in name:
        return name
    if preserve_snake_case and "_" in name:
        return name
    return humps.camelize(name)


def _source_path(value: Any) -> str | None:
    if isinstance(value, Blob) and value.source_path:
        return value.source_path
    if isinstance(value, Path):
        return str(value)
    if isinstance(value, str):
        return value
    return None


def _artifact_handle(value: Any) -> str | None:
    if isinstance(value, RemoteObject):
        return value._id
    return None


class _RpcUndefinedArg:
    pass


_RPC_UNDEFINED_ARG = _RpcUndefinedArg()
_RPC_DATE_KEY = "__rpcDate"


def _datetime_to_rpc_iso(value: date | datetime) -> str:
    """Encode Python temporal values for the RPC wire protocol.

    Granola's JS cell Date type is a timestamp. We normalize all Python inputs
    to UTC and emit ISO-8601 with a `Z` suffix so server-side reconstruction is
    deterministic across environments.

    - `date` values are interpreted as midnight UTC.
    - naive `datetime` values are interpreted as UTC.
    """
    if isinstance(value, datetime):
        dt = value
    else:
        dt = datetime.combine(value, time.min, tzinfo=timezone.utc)
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    else:
        dt = dt.astimezone(timezone.utc)
    return dt.isoformat(timespec="milliseconds").replace("+00:00", "Z")


def _rpc_iso_to_datetime(value: str) -> datetime | None:
    normalized = value[:-1] + "+00:00" if value.endswith("Z") else value
    try:
        parsed = datetime.fromisoformat(normalized)
    except ValueError:
        return None
    if parsed.tzinfo is None:
        return parsed.replace(tzinfo=timezone.utc)
    return parsed


def serialize(x: Any) -> Any:
    """
    Convert Python values to wire values.
    Remote objects become {"$ref": "..."}.
    """
    if isinstance(x, Blob):
        encoded = base64.b64encode(x.data).decode("ascii")
        payload: dict[str, Any] = {"__blob": True, "data": encoded}
        if x.mime is not None:
            payload["mime"] = x.mime
        return payload
    if isinstance(x, datetime):
        return {_RPC_DATE_KEY: _datetime_to_rpc_iso(x)}
    if isinstance(x, date):
        return {_RPC_DATE_KEY: _datetime_to_rpc_iso(x)}
    if isinstance(x, Enum):
        return serialize(x.value)
    if isinstance(x, _RpcUndefinedArg):
        return {"__rpcUndefined": True}
    if isinstance(x, RemoteObject):
        return {"$ref": x._id}
    if isinstance(x, RemoteAttr):
        # If a RemoteAttr is passed as an argument, resolve to its underlying value first.
        return serialize(x._resolve())
    if isinstance(x, list):
        return [serialize(v) for v in x]
    if isinstance(x, tuple):
        return [serialize(v) for v in x]
    if isinstance(x, dict):
        return _camelize_data({k: serialize(v) for k, v in x.items()})
    return x


def rpc_args(*args: Any) -> list[Any]:
    """
    Normalize generated wrapper args for RPC calls.

    Generated methods use Ellipsis as the "argument omitted" sentinel.

    - Trailing omitted args are dropped (equivalent to argument omission).
    - Interior omitted args are preserved as a wire sentinel so the daemon can
      map them to JS `undefined` without shifting positional arguments.
    """
    last_present_idx = -1
    for idx, arg in enumerate(args):
        if arg is not Ellipsis:
            last_present_idx = idx

    if last_present_idx < 0:
        return []

    normalized: list[Any] = []
    for arg in args[: last_present_idx + 1]:
        if arg is Ellipsis:
            normalized.append(_RPC_UNDEFINED_ARG)
        else:
            normalized.append(arg)
    return normalized


_HANDLE_LOCK = threading.Lock()
_HANDLE_CLIENTS: dict[str, weakref.ReferenceType[JsonRpcClient]] = {}
_EXIT_DISPOSE_TIMEOUT_S = 15.0


def _register_handle(client: JsonRpcClient, obj_id: str) -> None:
    with _HANDLE_LOCK:
        _HANDLE_CLIENTS[obj_id] = weakref.ref(client)


def _unregister_handle(obj_id: str) -> None:
    with _HANDLE_LOCK:
        _HANDLE_CLIENTS.pop(obj_id, None)


def _safe_dispose(client: JsonRpcClient, obj_id: str) -> None:
    try:
        client.call("dispose", {"target": obj_id})
        _unregister_handle(obj_id)
    except Exception:
        # Suppress errors during finalization; best-effort only.
        pass


def _safe_dispose_on_exit(client: JsonRpcClient, obj_id: str) -> None:
    try:
        # Exit handlers run before the owned daemon is stopped. Keep this
        # best-effort RPC from blocking interpreter shutdown indefinitely if
        # the daemon stops responding.
        client.call("dispose", {"target": obj_id}, timeout_s=_EXIT_DISPOSE_TIMEOUT_S)
    except Exception:
        # Closing the transport makes any remaining exit-time disposals fail
        # fast and lets daemon cleanup continue.
        client.close()


def _dispose_all_handles_on_exit() -> None:
    with _HANDLE_LOCK:
        items = list(_HANDLE_CLIENTS.items())
        _HANDLE_CLIENTS.clear()

    for obj_id, client_ref in items:
        client = client_ref()
        if client is None:
            continue
        _safe_dispose_on_exit(client, obj_id)


atexit.register(_dispose_all_handles_on_exit)


_GENERATED_MODELS_LOAD_LOCK = threading.Lock()
_GENERATED_MODELS_LOADED = False
_REMOTE_CLASS_CACHE_LOCK = threading.Lock()
_REMOTE_CLASS_CACHE: dict[str, type["RemoteClass"]] = {}
_TYPED_DICT_PROXY_CLASS_CACHE_LOCK = threading.Lock()
_TYPED_DICT_PROXY_CLASS_CACHE: dict[str, type["RemoteTypedDictObject"]] = {}


def _iter_remote_classes(cls: type["RemoteClass"]) -> list[type["RemoteClass"]]:
    classes: list[type["RemoteClass"]] = []
    for subclass in cls.__subclasses__():
        classes.append(subclass)
        classes.extend(_iter_remote_classes(subclass))
    return classes


def _find_remote_class(class_name: str) -> type["RemoteClass"] | None:
    for candidate in _iter_remote_classes(RemoteClass):
        if candidate.__name__ == class_name:
            return candidate
    return None


def _ensure_generated_models_loaded() -> None:
    global _GENERATED_MODELS_LOADED
    with _GENERATED_MODELS_LOAD_LOCK:
        if _GENERATED_MODELS_LOADED:
            return

    try:
        import_module("artifact_tool_v2.generated.interface.models")
        with _GENERATED_MODELS_LOAD_LOCK:
            _GENERATED_MODELS_LOADED = True
    except Exception:
        # Some consumers import the RPC layer directly and may not have generated
        # interface modules available. In that case we gracefully fall back.
        pass


def _resolve_remote_class(class_name: str | None) -> type["RemoteClass"] | None:
    if not class_name:
        return None

    with _REMOTE_CLASS_CACHE_LOCK:
        if class_name in _REMOTE_CLASS_CACHE:
            return _REMOTE_CLASS_CACHE[class_name]

    cls = _find_remote_class(class_name)
    if cls is None:
        _ensure_generated_models_loaded()
        cls = _find_remote_class(class_name)

    if cls is not None:
        with _REMOTE_CLASS_CACHE_LOCK:
            _REMOTE_CLASS_CACHE[class_name] = cls
    return cls


def _is_object_handle_payload(result: dict[str, Any]) -> bool:
    if "objectId" not in result or not isinstance(result.get("objectId"), str):
        return False
    allowed_keys = {"objectId", "class"}
    return set(result.keys()).issubset(allowed_keys)


def _resolve_typed_dict_proxy_class(class_name: str) -> type["RemoteTypedDictObject"] | None:
    with _TYPED_DICT_PROXY_CLASS_CACHE_LOCK:
        cached = _TYPED_DICT_PROXY_CLASS_CACHE.get(class_name)
    if cached is not None:
        return cached

    _ensure_generated_models_loaded()
    try:
        models = import_module("artifact_tool_v2.generated.interface.models")
        candidate = getattr(models, class_name)
    except Exception:
        return None

    if isinstance(candidate, type) and issubclass(candidate, RemoteTypedDictObject):
        with _TYPED_DICT_PROXY_CLASS_CACHE_LOCK:
            _TYPED_DICT_PROXY_CLASS_CACHE[class_name] = candidate
        return candidate
    return None


def _retag_remote_object(value: Any, cls: type["RemoteTypedDictObject"]) -> Any:
    if isinstance(value, cls):
        return value
    if isinstance(value, RemoteObject):
        try:
            value.__class__ = cls
        except TypeError:
            return cls(value._client, value._id, class_name=value._class)
        return value
    return value


def wrap_result(client: JsonRpcClient, result: Any) -> Any:
    """
    Convert wire results back into Python values.
    If Node returns {"objectId": "...", "class": "Slide"}, wrap into a RemoteObject (typed wrapper can be added later).
    """
    if isinstance(result, dict) and len(result) == 1 and isinstance(result.get(_RPC_DATE_KEY), str):
        parsed = _rpc_iso_to_datetime(result[_RPC_DATE_KEY])
        if parsed is not None:
            return parsed
    if isinstance(result, dict) and result.get("__blob") and "data" in result:
        data_b64 = result["data"]
        try:
            import base64

            raw = base64.b64decode(data_b64)
        except Exception:
            raw = b""
        return Blob(raw, mime=result.get("mime") or None)
    if isinstance(result, dict) and _is_object_handle_payload(result):
        class_name = result.get("class")
        typed_cls = _resolve_remote_class(class_name)
        if typed_cls is not None:
            return typed_cls._from_handle(
                client,
                result["objectId"],
                class_name=class_name,
            )
        return RemoteObject(client, result["objectId"], class_name=class_name)
    if isinstance(result, list):
        return [wrap_result(client, v) for v in result]
    if isinstance(result, dict):
        decamelized = _decamelize_data(result)
        return {k: wrap_result(client, v) for k, v in decamelized.items()}
    return result


@dataclass(frozen=True)
class _Handle:
    object_id: str
    class_name: str | None = None


class RemoteObject:
    """
    Represents a remote JS object by handle.
    Attribute access returns a RemoteAttr, which can act as:
      - a property (when you do further attribute access / use it as value)
      - a method (when you call it)
    """

    _client: JsonRpcClient
    _handle: _Handle

    def __init__(self, client: JsonRpcClient, object_id: str, class_name: str | None = None):
        object.__setattr__(self, "_client", client)
        object.__setattr__(self, "_handle", _Handle(object_id, class_name))
        # Best-effort cleanup; explicit dispose() remains the recommended path.
        finalizer = weakref.finalize(self, _safe_dispose, client, object_id)
        # The registry below owns interpreter-exit cleanup so it can use the
        # bounded RPC path. Keep this finalizer for ordinary garbage collection.
        finalizer.atexit = False
        object.__setattr__(self, "_finalizer", finalizer)
        _register_handle(client, object_id)

    @property
    def _id(self) -> str:
        return self._handle.object_id

    @property
    def _class(self) -> str | None:
        return self._handle.class_name

    def _remote_attr(self, name: str, *, preserve_snake_case: bool = False) -> "RemoteAttr":
        return RemoteAttr(self, name, preserve_snake_case=preserve_snake_case)

    def _remote_get(self, name: str, *, preserve_snake_case: bool = False) -> Any:
        return self._remote_attr(name, preserve_snake_case=preserve_snake_case)._resolve()

    def _remote_set(self, name: str, value: Any, *, preserve_snake_case: bool = False) -> None:
        self._client.call(
            "setAttr",
            {
                "target": self._id,
                "attr": _wire_attr(name, preserve_snake_case=preserve_snake_case),
                "value": serialize(value),
            },
        )

    def _snapshot(self, *, max_depth: int = 8) -> Any:
        result = self._client.call(
            "snapshot",
            {"target": self._id, "maxDepth": max(1, int(max_depth))},
        )
        return wrap_result(self._client, result)

    def dispose(self) -> bool:
        # Explicit, deterministic cleanup
        try:
            ok = bool(self._client.call("dispose", {"target": self._id}))
        except Exception:
            # Leave finalizer and registry intact so GC/atexit can retry.
            raise

        if ok:
            object.__getattribute__(self, "_finalizer").detach()
            _unregister_handle(self._id)
        return ok

    def __getattr__(self, name: str) -> "RemoteAttr":
        # Always return a dual-use proxy; it decides later if it's a property or method.
        return self._remote_attr(name)

    def __getitem__(self, name: str) -> "RemoteAttr":
        # Allow obj["attr"] as a synonym for obj.attr
        return self.__getattr__(name)

    def __setitem__(self, name: str, value: Any) -> None:
        # Allow obj["attr"] = value as a synonym for obj.attr = value
        self.__setattr__(name, value)

    def __setattr__(self, name: str, value: Any) -> None:
        # Remote property set
        if name.startswith("_"):
            object.__setattr__(self, name, value)
            return

        # Honor descriptor/property setters on generated wrapper classes first.
        # This lets generated setters supply wire-key behavior (e.g. preserve snake_case)
        # instead of always routing through generic attribute conversion.
        descriptor = None
        for cls in type(self).__mro__:
            if name in cls.__dict__:
                descriptor = cls.__dict__[name]
                break
        if descriptor is not None and hasattr(descriptor, "__set__"):
            object.__setattr__(self, name, value)
            return

        self._remote_set(name, value)

    def __repr__(self) -> str:
        cls = self._class or "RemoteObject"
        return f"<{cls} id={self._id}>"


_TypedDictPromoteSpec = Any
_T = TypeVar("_T")


class RemoteTypedDictObject(RemoteObject):
    """
    Proxy for JS plain-object results that are statically modeled as TypedDicts.

    Supports both attribute and item-style access while preserving remote mutation semantics.
    """

    def to_dict(self, *, max_depth: int = 8) -> dict[str, Any]:
        data = self._snapshot(max_depth=max_depth)
        if isinstance(data, dict):
            return cast(dict[str, Any], data)
        return {"value": data}

    def keys(self):
        return self.to_dict().keys()

    def items(self):
        return self.to_dict().items()

    def values(self):
        return self.to_dict().values()

    def _typed_dict_descriptor(self, name: str) -> Any:
        for cls in type(self).__mro__:
            if name in cls.__dict__:
                return cls.__dict__[name]
        return None

    def __getitem__(self, name: str) -> Any:
        descriptor = self._typed_dict_descriptor(name)
        if descriptor is not None and hasattr(descriptor, "__get__"):
            return getattr(self, name)
        return self._remote_get(name)

    def __setitem__(self, name: str, value: Any) -> None:
        descriptor = self._typed_dict_descriptor(name)
        if descriptor is not None and hasattr(descriptor, "__set__"):
            setattr(self, name, value)
            return
        self._remote_set(name, value)

    def __str__(self) -> str:
        return str(self.to_dict())

    def __repr__(self) -> str:
        return repr(self.to_dict())


def _promote_typed_dict_object(value: Any, proxy_class_name: str) -> Any:
    if not isinstance(value, RemoteObject):
        return value
    # Only promote plain JS object handles (TypedDict-like payloads). Real remote
    # class handles (e.g. Shape) can appear in unions and must keep their class.
    if not isinstance(value, RemoteTypedDictObject) and value._class not in (None, "Object"):
        return value
    proxy_cls = _resolve_typed_dict_proxy_class(proxy_class_name)
    if proxy_cls is None:
        return value
    return _retag_remote_object(value, proxy_cls)


def promote_typed_dict_result(value: _T, spec: _TypedDictPromoteSpec) -> _T:
    """
    Best-effort promotion of RemoteObject handles into generated RemoteTypedDictObject subclasses.

    `spec` is a codegen-emitted nested tuple:
      ("typed_dict", "FooObject")
      ("list", <spec>)
      ("tuple", [<spec>...])
      ("tuple_variadic", <spec>)
      ("dict", <key_spec>, <value_spec>)
      ("union", [<spec-or-None>...])
    """
    if spec is None:
        return value
    if isinstance(spec, tuple):
        tag = spec[0]
        if tag == "typed_dict":
            return cast(_T, _promote_typed_dict_object(value, spec[1]))
        if tag == "list":
            if isinstance(value, list):
                inner = spec[1]
                return cast(_T, [promote_typed_dict_result(item, inner) for item in value])
            return value
        if tag == "tuple":
            if isinstance(value, tuple):
                item_specs = spec[1]
                return cast(
                    _T,
                    tuple(
                        promote_typed_dict_result(
                            item, item_specs[idx] if idx < len(item_specs) else None
                        )
                        for idx, item in enumerate(value)
                    ),
                )
            return value
        if tag == "tuple_variadic":
            if isinstance(value, tuple):
                inner = spec[1]
                return cast(_T, tuple(promote_typed_dict_result(item, inner) for item in value))
            return value
        if tag == "dict":
            if isinstance(value, dict):
                key_spec = spec[1]
                value_spec = spec[2]
                return cast(
                    _T,
                    {
                        promote_typed_dict_result(k, key_spec): promote_typed_dict_result(
                            v, value_spec
                        )
                        for k, v in value.items()
                    },
                )
            return value
        if tag == "union":
            choices = spec[1]
            if value is None:
                return value
            if isinstance(value, RemoteObject):
                for choice in choices:
                    if isinstance(choice, tuple) and choice and choice[0] == "typed_dict":
                        return cast(_T, promote_typed_dict_result(value, choice))
            for choice in choices:
                promoted = promote_typed_dict_result(value, choice)
                if promoted is not value:
                    return cast(_T, promoted)
            return value
    return value


class RemoteAttr:
    """
    Dual-use proxy for obj.attr in JS.

    - Calling it: obj.attr(...)  -> RPC "call" (method invocation)
    - Accessing sub-attrs: obj.attr.sub -> resolves obj.attr as a property first
    - Representing/using it: tries to behave like the resolved value
    """

    def __init__(self, target: RemoteObject, name: str, *, preserve_snake_case: bool = False):
        object.__setattr__(self, "_target", target)
        object.__setattr__(self, "_name", name)
        object.__setattr__(self, "_preserve_snake_case", preserve_snake_case)
        object.__setattr__(self, "_cached", None)  # optional caching of resolved property

    def _resolve(self) -> Any:
        cached = object.__getattribute__(self, "_cached")
        if cached is not None:
            return cached

        target = object.__getattribute__(self, "_target")
        name = object.__getattribute__(self, "_name")
        preserve_snake_case = object.__getattribute__(self, "_preserve_snake_case")

        result = target._client.call(
            "getAttr",
            {
                "target": target._id,
                "attr": _wire_attr(name, preserve_snake_case=preserve_snake_case),
            },
        )
        wrapped = wrap_result(target._client, result)

        object.__setattr__(self, "_cached", wrapped)
        return wrapped

    def __call__(self, *args: Any, **kwargs: Any) -> Any:
        if kwargs:
            # JS does not have kwargs, so passing them over RPC doesn't make sense.
            # However, once we have information about the set of arguments that a JS method expects
            # and their names, we can start mapping kwargs to args here.
            # TODO: Support keyword arguments.
            raise TypeError("Keyword arguments not supported")

        target = object.__getattribute__(self, "_target")
        name = object.__getattribute__(self, "_name")
        preserve_snake_case = object.__getattribute__(self, "_preserve_snake_case")

        result = target._client.call(
            "call",
            {
                "target": target._id,
                "method": _wire_attr(name, preserve_snake_case=preserve_snake_case),
                "args": serialize(rpc_args(*args)),
            },
        )
        return wrap_result(target._client, result)

    def __getattr__(self, subname: str) -> Any:
        # Property chaining: presentation.slides.add()
        resolved = self._resolve()
        return getattr(resolved, subname)

    def __setattr__(self, subname: str, value: Any) -> None:
        # If someone does: presentation.slides.foo = 1
        resolved = self._resolve()
        setattr(resolved, subname, value)

    def __repr__(self) -> str:
        # Make it pleasant in REPL/debugger
        try:
            v = self._resolve()
            return repr(v)
        except Exception:
            target = object.__getattribute__(self, "_target")
            name = object.__getattribute__(self, "_name")
            return f"<RemoteAttr {target}.{name}>"

    # Optional conveniences so RemoteAttr "feels" like the resolved value in common cases.
    @staticmethod
    def _coerce_other(other: object) -> object:
        if isinstance(other, RemoteAttr):
            return other._resolve()
        return other

    def __eq__(self, other: object) -> bool:
        resolved = self._resolve()
        return resolved == self._coerce_other(other)

    def __ne__(self, other: object) -> bool:
        resolved = self._resolve()
        return resolved != self._coerce_other(other)

    def __lt__(self, other: object) -> bool:
        resolved = self._resolve()
        return resolved < self._coerce_other(other)

    def __le__(self, other: object) -> bool:
        resolved = self._resolve()
        return resolved <= self._coerce_other(other)

    def __gt__(self, other: object) -> bool:
        resolved = self._resolve()
        return resolved > self._coerce_other(other)

    def __ge__(self, other: object) -> bool:
        resolved = self._resolve()
        return resolved >= self._coerce_other(other)

    def __hash__(self) -> int:
        return hash(self._resolve())

    def __add__(self, other: object):
        return self._resolve() + self._coerce_other(other)

    def __radd__(self, other: object):
        return self._coerce_other(other) + self._resolve()

    def __sub__(self, other: object):
        return self._resolve() - self._coerce_other(other)

    def __rsub__(self, other: object):
        return self._coerce_other(other) - self._resolve()

    def __mul__(self, other: object):
        return self._resolve() * self._coerce_other(other)

    def __rmul__(self, other: object):
        return self._coerce_other(other) * self._resolve()

    def __truediv__(self, other: object):
        return self._resolve() / self._coerce_other(other)

    def __rtruediv__(self, other: object):
        return self._coerce_other(other) / self._resolve()

    def __floordiv__(self, other: object):
        return self._resolve() // self._coerce_other(other)

    def __rfloordiv__(self, other: object):
        return self._coerce_other(other) // self._resolve()

    def __mod__(self, other: object):
        return self._resolve() % self._coerce_other(other)

    def __rmod__(self, other: object):
        return self._coerce_other(other) % self._resolve()

    def __pow__(self, other: object):
        return self._resolve() ** self._coerce_other(other)

    def __rpow__(self, other: object):
        return self._coerce_other(other) ** self._resolve()

    def __neg__(self):
        return -self._resolve()

    def __pos__(self):
        return +self._resolve()

    def __abs__(self):
        return abs(self._resolve())

    def __iter__(self):
        return iter(self._resolve())

    def __len__(self):
        return len(self._resolve())

    def __getitem__(self, k):
        return self._resolve()[k]

    def __int__(self):
        return int(self._resolve())

    def __index__(self):
        return int(self)

    def __float__(self):
        return float(self._resolve())

    def __bool__(self):
        return bool(self._resolve())

    def __str__(self):
        return str(self._resolve())

    def __format__(self, format_spec: str):
        return format(self._resolve(), format_spec)


class RemoteClassAttr:
    """
    Proxy for static/class methods on RemoteClass subclasses.
    Calling the attribute dispatches via callStatic.
    """

    def __init__(self, cls: type["RemoteClass"], name: str, *, preserve_snake_case: bool = False):
        object.__setattr__(self, "_cls", cls)
        object.__setattr__(self, "_name", name)
        object.__setattr__(self, "_preserve_snake_case", preserve_snake_case)

    def __call__(self, *args: Any, **kwargs: Any) -> Any:
        if kwargs:
            # JS does not have kwargs, so passing them over RPC doesn't make sense.
            # However, once we have information about the set of arguments that a JS method expects
            # and their names, we can start mapping kwargs to args here.
            # TODO: Support keyword arguments.
            raise TypeError("Keyword arguments not supported")
        cls = object.__getattribute__(self, "_cls")
        name = object.__getattribute__(self, "_name")
        preserve_snake_case = object.__getattribute__(self, "_preserve_snake_case")
        return cls.call_static(name, *args, preserve_snake_case=preserve_snake_case)

    def __repr__(self) -> str:
        cls = object.__getattribute__(self, "_cls")
        name = object.__getattribute__(self, "_name")
        return f"<RemoteClassAttr {cls.__name__}.{name}>"


class RemoteClassMeta(type):
    def __call__(cls, *args: Any, **kwargs: Any):
        # Route construction over RPC instead of creating a local Python instance.
        if kwargs:
            # JS does not have kwargs, so passing them over RPC doesn't make sense.
            # However, once we have information about the set of arguments that a JS method expects
            # and their names, we can start mapping kwargs to args here.
            # TODO: Support keyword arguments.
            raise TypeError("Keyword arguments not supported")
        return cls.construct(*args)

    def __getattr__(cls, name: str) -> RemoteClassAttr:
        if name.startswith("_"):
            raise AttributeError(name)
        return RemoteClassAttr(cast(type["RemoteClass"], cls), name)


class RemoteClass(RemoteObject, metaclass=RemoteClassMeta):
    _client: JsonRpcClient | None = None

    @classmethod
    def _from_handle(
        cls,
        client: JsonRpcClient,
        object_id: str,
        *,
        class_name: str | None = None,
    ) -> "RemoteClass":
        """
        Build a typed wrapper instance for an existing remote handle.
        This bypasses RemoteClassMeta.__call__, which is reserved for remote construction.
        """
        instance = object.__new__(cls)
        RemoteObject.__init__(instance, client, object_id, class_name or cls.__name__)
        return cast(RemoteClass, instance)

    @classmethod
    def _bind_client(cls, client: JsonRpcClient) -> None:
        """This is automatically called during setup and should not be called directly by consumers."""
        cls._client = client

    @classmethod
    def _ensure_client(cls) -> JsonRpcClient:
        if RemoteClass._client is None:
            client = get_or_create_client()
            RemoteClass._bind_client(client)
        assert RemoteClass._client is not None
        return RemoteClass._client

    @classmethod
    def construct(cls, *args: Any) -> RemoteObject:
        client = cls._ensure_client()
        result = client.call(
            "construct",
            {"class": cls.__name__, "args": serialize(rpc_args(*args))},
        )
        return wrap_result(client, result)

    @classmethod
    def call_static(cls, method: str, *args: Any, preserve_snake_case: bool = False) -> Any:
        client = cls._ensure_client()
        wire_method = _wire_attr(method, preserve_snake_case=preserve_snake_case)
        result = client.call(
            "callStatic",
            {
                "class": cls.__name__,
                "method": wire_method,
                "args": serialize(rpc_args(*args)),
            },
        )
        wrapped = wrap_result(client, result)

        import_spec = _FILE_IMPORT_OPS.get((cls.__name__, wire_method))
        if import_spec is not None:
            load_op, file_format = import_spec
            artifact_handle = _artifact_handle(wrapped)
            source_path = _source_path(args[0]) if args else None
            if artifact_handle and source_path:
                client.record_artifact_operation(
                    artifact_handle,
                    {
                        "op": load_op,
                        "path": source_path,
                        "format": file_format,
                    },
                )

        export_spec = _FILE_EXPORT_OPS.get((cls.__name__, wire_method))
        if export_spec is not None:
            save_op, file_format = export_spec
            artifact_handle = _artifact_handle(args[0]) if args else None
            if artifact_handle and isinstance(wrapped, Blob):
                wrapped = replace(
                    wrapped,
                    artifact_handle=artifact_handle,
                    artifact_format=file_format,
                    artifact_save_op=save_op,
                )

        return wrapped
